const lessons = [
  {id:'basics',no:'01',title:'先认识“量”',subtitle:'从一句话里找出能变的数字',tag:'数学语言',intro:'数量关系不是先找公式，而是先问：题目里有哪几个量？谁随着谁变化？',insight:'把“一共”想成许多相同小份加起来。3 支笔每支 4 元，就是 3 个 4 元。',formula:'总价 = 单价 × 数量',steps:[['找对象','有多少支笔？每支多少钱？'],['找关系','每多一支，总价增加一个单价。'],['写算式','相同的几份，用乘法连起来。']],example:'一支笔 4 元，买 5 支需要多少钱？',solution:['单价是 4 元，数量是 5 支。','总价 = 4 × 5 = 20 元。','反过来检查：20 ÷ 5 = 4 元/支。'],pitfall:'“每”往往提示单位量；“一共”往往提示求总量。',quiz:{prompt:'一盒彩笔 6 元，买 4 盒，一共需要多少元？',options:['10 元','20 元','24 元','30 元'],answer:2,hint:'把 4 个 6 元加起来，也可以用乘法。',explain:'6 × 4 = 24 元。先辨认单价与数量，再求总价。'},explorer:'basics'},
  {id:'equation',no:'02',title:'把文字翻译成等式',subtitle:'用一个未知数搭出“天平”',tag:'数学语言',intro:'有些题先不必求答案。把已知条件准确放到等号两边，难题就变成了可计算的等式。',insight:'“比原来多 7 个”是原来的数量 + 7；“一共 19 个”是等号另一边的总量。',formula:'原来的量 + 增加的量 = 现在的量',steps:[['设未知','不知道的量，暂时叫 x。'],['翻译词语','“多 7”写成 x + 7。'],['保持平衡','等号两边同时减 7，得到 x。']],example:'盒里原来有一些球，又放入 7 个，现在有 19 个。原来有几个？',solution:['设原来有 x 个。','x + 7 = 19。','等号两边同时减 7，x = 12。'],pitfall:'“比 A 多 7”指 A + 7；一定先确定谁是参照量。',quiz:{prompt:'一桶水用掉 8 升后还剩 15 升，原来有多少升？',options:['7 升','15 升','23 升','120 升'],answer:2,hint:'原来 − 用掉 = 剩下。',explain:'设原来有 x 升，x − 8 = 15，所以 x = 23。'},explorer:'equation'},
  {id:'work',no:'03',title:'工程问题',subtitle:'把“一项任务”切成均匀小块',tag:'高频题型',intro:'工程问题关注三件事：总共要做多少、每天能做多少、需要多少天。合作时，每天完成量可以相加。',insight:'甲 6 天做完、乙 8 天做完，可先把总量想成 24 份：甲每天 4 份，乙每天 3 份。',formula:'工作总量 = 工作效率 × 工作时间',steps:[['赋总量','把总任务设为两个时间的公倍数。'],['求效率','每人的效率 = 总量 ÷ 单独时间。'],['算合作','合作时间 = 总量 ÷ 效率之和。']],example:'甲独做 6 天，乙独做 8 天。两人合作几天完成？',solution:['设总量为 24 份。','甲每天 4 份，乙每天 3 份。','合作每天 7 份，需 24 ÷ 7 ≈ 3.43 天。'],pitfall:'合作效率是“每天完成量”相加，不是两个天数相加。',quiz:{prompt:'甲独做 6 天，乙独做 3 天。合作完成需要几天？',options:['1 天','2 天','3 天','9 天'],answer:1,hint:'把总量设成 6 份，甲每天 1 份，乙每天 2 份。',explain:'每天合做 3 份，6 ÷ 3 = 2 天。'},explorer:'work'},
  {id:'motion',no:'04',title:'行程问题',subtitle:'让路程、速度、时间动起来',tag:'高频题型',intro:'速度表示单位时间走过的路程。两人相向而行时，两人的速度都在缩短中间的距离。',insight:'相向而行看速度和，追赶同向看速度差。先画出方向，公式就不容易用反。',formula:'路程 = 速度 × 时间',steps:[['画方向','先看相向、同向还是往返。'],['统一单位','公里、小时要配套使用。'],['找速度关系','相遇用速度和，追及用速度差。']],example:'两地相距 150 公里，甲乙相向而行，速度分别为 60、40 公里/时，多久相遇？',solution:['一小时内，两人合计靠近 60 + 40 = 100 公里。','需要缩短 150 公里。','时间 = 150 ÷ 100 = 1.5 小时。'],pitfall:'相向而行要相加；同向追及才常用相减。',quiz:{prompt:'两车相距 180 公里，相向开来，速度分别为 60 和 30 公里/时。几小时相遇？',options:['1 小时','2 小时','3 小时','6 小时'],answer:1,hint:'每小时一起缩短 60 + 30 = 90 公里。',explain:'180 ÷ (60 + 30) = 2 小时。'},explorer:'motion'},
  {id:'profit',no:'05',title:'利润与折扣',subtitle:'从成本 100 元开始想',tag:'高频题型',intro:'题目出现百分比时，先找百分比是“以谁为基准”。利润率通常以成本为分母。',insight:'成本设成 100 元后，20% 利润就是 20 元；八折意味着售价乘 0.8。',formula:'利润率 = (售价 − 成本) ÷ 成本',steps:[['找基准','成本、标价、实售价分别是多少？'],['按顺序变','先打折，再减成本。'],['算利润率','利润除以成本，不是除以售价。']],example:'成本 100 元，标价 150 元，打八折卖出。利润率是多少？',solution:['实售价 = 150 × 0.8 = 120 元。','利润 = 120 − 100 = 20 元。','利润率 = 20 ÷ 100 = 20%。'],pitfall:'八折是乘 80%；降价 8% 是乘 92%，两者不一样。',quiz:{prompt:'一件商品成本 80 元，售价 100 元，利润率是多少？',options:['20%','25%','80%','125%'],answer:1,hint:'利润 20 元，要除以成本 80 元。',explain:'(100 − 80) ÷ 80 = 25%。'},explorer:'profit'},
  {id:'sets',no:'06',title:'容斥原理',subtitle:'让重复的人只数一次',tag:'高频题型',intro:'两群人有重叠时，直接把人数相加会把中间那群人算两次。用圆圈把重叠区画出来。',insight:'会 A 的人数 + 会 B 的人数，重复算了“都会”的人数一次，所以要减回来。',formula:'至少会一种 = A + B − 两种都会',steps:[['画两个圈','一个圈代表 A，一个圈代表 B。'],['填重叠区','把“两者都满足”的人放中间。'],['只数一次','相加后减去一次重叠。']],example:'全班 40 人，会英语 25 人，会法语 20 人，两种都会 10 人。两种都不会的有几人？',solution:['至少会一种 = 25 + 20 − 10 = 35 人。','全班 40 人。','都不会 = 40 − 35 = 5 人。'],pitfall:'“只会 A”和“会 A”不同；后者包含两种都会的人。',quiz:{prompt:'50 人中，30 人会英语，25 人会法语，10 人两种都会。两种都不会的有几人？',options:['0 人','5 人','10 人','15 人'],answer:1,hint:'先求至少会一门：30 + 25 − 10。',explain:'至少会一门 45 人，都不会 = 50 − 45 = 5 人。'},explorer:'sets'},
  {id:'mixture',no:'07',title:'浓度问题',subtitle:'水变多，溶质不会凭空增加',tag:'高频题型',intro:'浓度是“溶质占整杯溶液的比例”。只加水时，溶质不变，总量增加，所以浓度下降。',insight:'不必背十字交叉法，先守住不变量：加水不改变溶质的质量。',formula:'浓度 = 溶质质量 ÷ 溶液总质量',steps:[['求溶质','原溶液 × 原浓度。'],['更新总量','加入水后，溶液总量增加。'],['重新相除','新浓度 = 原溶质 ÷ 新总量。']],example:'100 克、20% 的盐水，再加入 100 克清水，新浓度是多少？',solution:['原溶质 = 100 × 20% = 20 克。','新溶液总量 = 100 + 100 = 200 克。','新浓度 = 20 ÷ 200 = 10%。'],pitfall:'加水时变的是总质量，不是盐的质量。',quiz:{prompt:'200 克、10% 的盐水，加入 200 克清水后，浓度是多少？',options:['2.5%','5%','10%','20%'],answer:1,hint:'盐仍是 20 克，现在一共 400 克。',explain:'20 ÷ 400 = 5%。'},explorer:'mixture'},
  {id:'counting',no:'08',title:'排列与组合',subtitle:'先问顺序重不重要',tag:'进阶入门',intro:'“从 5 人中选 2 名代表”与“选队长和副队长”不同。前者不分顺序，后者分角色，因此结果数量不同。',insight:'两人互换后仍是同一种选择，就是组合；互换后变成另一种结果，就是排列。',formula:'有顺序用排列 · 无顺序用组合',steps:[['先问顺序','A、B 互换是否算新结果？'],['分步选择','有顺序时，先选第一位再选第二位。'],['去掉重复','无顺序时，同一组的不同顺序只算一次。']],example:'5 人中选 2 名代表，有多少种选法？',solution:['先按顺序选：第一人有 5 种，第二人有 4 种，共 20 种。','每组两人被算了 2 次，例如甲乙和乙甲。','20 ÷ 2 = 10 种。'],pitfall:'“选人”和“安排职位”常常不是同一道题。',quiz:{prompt:'5 人中选 1 名队长、1 名副队长，共有多少种安排？',options:['10 种','15 种','20 种','25 种'],answer:2,hint:'队长和副队长交换后，是新的安排。',explain:'队长有 5 种选法，副队长剩 4 种，共 5 × 4 = 20 种。'},explorer:'counting'}
];

