const examBridge={
  basics:{signal:'文字里同时出现“总数、比例、分组、剩余”时，先确认每个数字的分母是谁。',model:'把总数记为 N，每一类写成 N 的一部分；人数和件数必须是整数，还可用整除条件缩小范围。',method:'先列“整体 → 分组 → 剩余”的表，再按题目顺序扣除，最后用总数验算。',decision:'例如真题第 66 题：70 多人中的 96% 是整数，先锁定总人数 75，比逐个选项代入快。',challenge:'把“某类占 20%”改成“占赴西部人数的 20%”，分母会从 75 变成 72；先圈出“占谁”。'},
  equation:{signal:'两种购买方案、前后转移或“比……多”的条件，往往在描述同一个总量或同一个差额。',model:'用未知数表示最少的核心量；把每一种情形各写一条等式，并标清正负号与单位。',method:'优先找不变量：原有资金不变、总藏书不变。转移 150 本时，甲乙差额减少 300 本。',decision:'第 61 题先把两种标准写成 100x＋550＝120x－630；第 64 题可以直接利用差额变化，不必先设两馆本数。',challenge:'限时练习时先判断能否用“差量”或选项代入；如果只剩一元一次式，就不要铺开多个未知数。'},
  work:{signal:'出现多条生产线、分段合作、不同开始时间时，先区分“效率”和“已完成量”。',model:'每条线的累计产量＝效率×实际生产时长；效率相同的两条线在同一时间内产量增加相同。',method:'如果两条线效率相同，它们在同一时刻的累计产量差不变；先用差量求中午已完成量，再算后续合计效率。',decision:'第 74 题不必先求两条线各自的开工时间，直接用 y－x＝x－54＝1.5x－y。',challenge:'到达目标数量时先扣掉已完成量，再除以后续参与生产的所有生产线的效率之和。'},
  motion:{signal:'看到“前 25% 路程加速、后 75% 匀速”或“正西、正北”时，先画分段线和方向图。',model:'每一段分别用 时间＝路程÷速度；匀加速段若给出始末速度，平均速度是两者的算术平均。直角方向的直线距离用勾股。',method:'比较前后半程时，把相同速度的路段抵消，只留下速度不同的那 1/4 路程；位置题则列坐标或直角边。',decision:'第 65 题的 3 分钟，只来自第一季度路程速度 18 与 21 的差；第 68 题可从 5-12-13 勾股数切入。',challenge:'先统一“分钟 / 小时”。算出时间差后，再代回原条件核对，不要把行驶路程当作两人的直线距离。'},
  profit:{signal:'“增长 20%”“售价提高”“降价后打折”“日产量变动”分别作用在不同基数上。',model:'销售额＝单价×数量；利润＝售价－成本；总利润＝单件利润×销售件数。多次变化按发生顺序写括号。',method:'第 67 题把去年产量设 5x、今年 6x；第 72 题同时乘日产量系数 0.9；第 75 题把降价和折扣严格按顺序算。',decision:'先问最终所求是收入、单件利润、利润率，还是每天总利润；模型不同，不能只套一个百分数公式。',challenge:'遇到“成本的 1.5 倍”，可把成本设 2x、标价设 3x，让分数条件先变成整数关系。'},
  sets:{signal:'“至少一种、两者都、只会 A、两者都不会”对应四个不同区域。',model:'全集 N＝只 A＋只 B＋两者都＋都不；A∪B＝A＋B－A∩B。',method:'先填交集，再算“只 A / 只 B”；如果给的是“只 A”，就不要再次从 A 中扣交集。',decision:'遇到多条件题，先画区域或四列表；题目没有给全集时，不能直接求“都不”。',challenge:'两个集合若互斥，交集是 0；若一个完全包含另一个，交集是较小集合。用边界检查答案。'},
  mixture:{signal:'加水、蒸发、倒出一部分、混合两杯，改变的量各不相同。',model:'溶质质量＝溶液质量×浓度；加水时溶质不变，蒸发纯水时溶质也不变，倒出均匀溶液时溶质与溶液同比例减少。',method:'先做“操作前 / 操作后”两列表，追踪溶质和总质量，再计算新浓度。',decision:'例如 20% 盐水加水变为 10%，是总质量翻倍；如果是倒出一半再加水，溶质先减半，不能沿用同一式子。',challenge:'两杯混合时用加权平均；新浓度必在两杯原浓度之间，可用这个范围快速排除错项。'},
  counting:{signal:'题目若只说“分成两组”，交换组名不产生新结果；若指定队长、副队长，交换角色产生新结果。',model:'有序选择：逐位相乘；无序选择：除去同一组的重复排列。平均分组且组无名称时，还要除以组间交换次数。',method:'第 69 题先算 C(6,3)/2＝10 种，再用补集排除不满足专业与宣传条件的分组。',decision:'正面分类很复杂时，先找“全部可能－不合格”；只有不合格情形容易列清且不重叠时才这样做。',challenge:'6 人分为两个 3 人组若标为 A、B 组是 20 种；不标组名才是 10 种，先读清题意。'}
};
