document.getElementById('review-list').addEventListener('click',event=>{const button=event.target.closest('[data-retry]');if(!button||!button.dataset.retry.startsWith('real:'))return;event.stopImmediatePropagation();const number=Number(button.dataset.retry.slice(5));document.getElementById('real-topic').value='all';document.getElementById('real-level').value='all';loadRealQuestions().then(()=>{realIndex=realCatalog.questions.findIndex(q=>q.number===number);switchView('real')})},true);

refreshStats();renderLesson();renderSpatialQuiz();document.querySelector('.spatial-quiz').insertAdjacentHTML('afterend','<div id="spatial-practice"></div>');renderPractice('spatial-practice','cube');switchView(location.hash.slice(1)||'home',false);

// Model-generated exercises use the current lesson as a fixed knowledge-point route.
function practiceNotice(root,message,isError=false){const slot=root.querySelector('.practice-status');slot.textContent=message;slot.classList.toggle('error',isError)}
function renderPractice(rootId,topic){const root=document.getElementById(rootId);if(!root)return;const title=practiceTitles[topic]||'当前知识点';root.innerHTML=`<section class="practice-card" aria-label="${title} AI 同类练习"><div class="practice-head"><div><span class="section-kicker">AI PRACTICE / SAME CONCEPT</span><h3>${title} · 再练一题</h3><p>同一个知识点，换一道新题。先在草稿纸上试，再对照逐步解法。</p></div><button class="primary-btn" type="button" data-practice-generate>出一道同类题 ↗</button></div><div class="practice-config"><label>模型<select data-practice-model><option value="glm-5.3-flash">GLM-5.3-Flash</option><option value="glm-5.3">GLM-5.3</option><option value="deepseek-flash">DeepSeek-V4.1-Flash · 支持图片</option><option value="deepseek-v4-pro">DeepSeek-V4-Pro · 深度推理</option></select></label><label>难度<select data-practice-level><option value="basic">入门</option><option value="standard">巩固</option><option value="challenge">挑战</option></select></label><label>模型 API Key<input data-practice-key type="password" autocomplete="off" spellcheck="false" placeholder="输入你自己的 Key"></label></div><p class="practice-note">与 AI 答疑共用本页输入的 Key；仅用于本次模型请求。题目由 AI 生成，请核对条件与解法。</p><div class="practice-status" role="status"></div><div class="practice-result"></div></section>`;
  const key=root.querySelector('[data-practice-key]');key.value=apiKeyMemory;key.addEventListener('input',()=>{apiKeyMemory=key.value;const shared=document.getElementById('ask-key');if(shared)shared.value=apiKeyMemory;document.querySelectorAll('[data-practice-key]').forEach(input=>{if(input!==key)input.value=apiKeyMemory})});
  const model=root.querySelector('[data-practice-model]');model.value=practiceModel;model.addEventListener('change',()=>{practiceModel=model.value;document.querySelectorAll('[data-practice-model]').forEach(select=>{if(select!==model)select.value=practiceModel})});
  const level=root.querySelector('[data-practice-level]');level.value=practiceLevel;level.addEventListener('change',()=>{practiceLevel=level.value;document.querySelectorAll('[data-practice-level]').forEach(select=>{if(select!==level)select.value=practiceLevel})});
  root.querySelector('[data-practice-generate]').addEventListener('click',()=>generatePractice(root,topic));
  if(practiceState.has(topic))showExercise(root,topic);
}
function parseDirectPractice(content,topic){const trimmed=content.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const start=trimmed.indexOf('{');const end=trimmed.lastIndexOf('}');if(start<0||end<start)throw new Error('模型返回的题目格式无法解析。');let value;try{value=JSON.parse(trimmed.slice(start,end+1))}catch{throw new Error('模型返回的题目格式无法解析。')}const {stem,options,correctIndex,finalAnswer,hint,steps,check,pitfall}=value;if(typeof stem!=='string'||stem.length<12||!Array.isArray(options)||options.length!==4||options.some(x=>typeof x!=='string'||!x.trim())||new Set(options).size!==4||!Number.isInteger(correctIndex)||correctIndex<0||correctIndex>3||finalAnswer!==options[correctIndex]||typeof hint!=='string'||!Array.isArray(steps)||steps.length<3||steps.length>7||steps.some(x=>typeof x!=='string'||x.length<6)||typeof check!=='string'||typeof pitfall!=='string')throw new Error('模型出题格式或答案校验未通过，请重试生成。');return{topic,topicName:practiceTitles[topic],stem,options,correctIndex,finalAnswer,hint,steps,check,pitfall}}
function practicePrompt(topic,level,previousStem){const lesson=lessons.find(item=>item.id===topic);return `围绕行测知识点“${practiceTitles[topic]||topic}”生成一道全新四选一练习题。难度：${{basic:'零基础入门',standard:'巩固练习',challenge:'进阶挑战'}[level]||level}。核心规则：${lesson?.formula||''} ${lesson?.insight||''}。题干应有唯一答案，避免与上一题重复：${previousStem||'无'}。请先独立求解并复核，再只输出 JSON，不要 Markdown。字段必须是 stem、options（4个字符串）、correctIndex（0到3）、finalAnswer（与正确选项完全相同）、hint、steps（3到7条详细步骤）、check、pitfall。步骤要说明为什么这样列式或判断，并给出验算。`}
async function generatePractice(root,topic){if(practiceBusy){practiceNotice(root,'上一道题仍在生成，请稍等。');return}const apiKey=apiKeyMemory.trim();if(!apiKey){practiceNotice(root,'请先输入你的模型 API Key。',true);root.querySelector('[data-practice-key]').focus();return}practiceBusy=true;const button=root.querySelector('[data-practice-generate]');button.disabled=true;button.textContent='正在出题…';practiceNotice(root,'AI 正在围绕当前知识点出题并检查解法…');try{const previousStem=practiceState.get(topic)?.exercise?.stem?.slice(0,500);let exercise;try{const content=await directModel(practiceModel,apiKey,[{role:'system',content:'你是严谨的行测出题老师。只输出用户要求的 JSON。'},{role:'user',content:practicePrompt(topic,practiceLevel,previousStem)}],2400);exercise=parseDirectPractice(content,topic);practiceNotice(root,`已直连 ${MODEL_CONFIG[practiceModel].label} 生成。`)}catch(directError){const response=await fetch('/api/practice',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apiKey,model:practiceModel,topic,level:practiceLevel,previousStem}),cache:'no-store',credentials:'same-origin'});const data=await response.json();if(!response.ok)throw new Error(data.error||directError.message||'生成失败，请稍后重试。');exercise=data.exercise;practiceNotice(root,'已通过本站服务端生成。')}practiceState.set(topic,{exercise,choice:null,revealed:false,hint:false});if(root.isConnected){showExercise(root,topic);practiceNotice(root,'新题已生成。先试着解，再查看详细解法。')}}catch(err){if(root.isConnected)practiceNotice(root,err.message||'生成失败，请稍后重试。',true)}finally{practiceBusy=false;if(root.isConnected){button.disabled=false;button.textContent=practiceState.has(topic)?'再来一道 ↗':'出一道同类题 ↗'}}}
function showExercise(root,topic){const entry=practiceState.get(topic);if(!entry)return;const exercise=entry.exercise;const result=root.querySelector('.practice-result');result.replaceChildren();const box=document.createElement('div');box.className='generated-question';const heading=document.createElement('h4');heading.textContent='原创模拟题 · '+exercise.topicName;const stem=document.createElement('p');stem.textContent=exercise.stem;box.append(heading,stem);const options=document.createElement('div');options.className='generated-options';exercise.options.forEach((option,index)=>{const button=document.createElement('button');button.type='button';const letter=document.createElement('b');letter.textContent='ABCD'[index];button.append(letter,document.createTextNode(option));if(entry.revealed){button.disabled=true;if(index===exercise.correctIndex)button.classList.add('correct');if(entry.choice===index&&index!==exercise.correctIndex)button.classList.add('wrong')}else button.addEventListener('click',()=>{entry.choice=index;entry.revealed=true;state.attempts.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),kind:'ai-practice',topic,correct:index===exercise.correctIndex,date:new Date().toISOString()});save();showExercise(root,topic)});options.append(button)});box.append(options);
  if(!entry.revealed){const actions=document.createElement('div');actions.className='generated-help';const hint=document.createElement('button');hint.className='text-btn';hint.type='button';hint.textContent=entry.hint?'收起提示':'给我一点提示 →';hint.addEventListener('click',()=>{entry.hint=!entry.hint;showExercise(root,topic)});const reveal=document.createElement('button');reveal.className='text-btn';reveal.type='button';reveal.textContent='直接看详细解法 →';reveal.addEventListener('click',()=>{entry.revealed=true;showExercise(root,topic)});const draft=document.createElement('button');draft.className='text-btn';draft.type='button';draft.textContent='打开草稿纸 ✎';draft.addEventListener('click',()=>document.getElementById('draft-toggle').click());actions.append(hint,reveal,draft);box.append(actions);if(entry.hint){const tip=document.createElement('div');tip.className='generated-hint';tip.textContent='提示：'+exercise.hint;box.append(tip)}}
  if(entry.revealed){const feedback=document.createElement('div');feedback.className='generated-feedback '+(entry.choice===exercise.correctIndex?'good':'bad');feedback.textContent=entry.choice===null?'先看懂解法，再试下一题。':entry.choice===exercise.correctIndex?'答对了！下面看每一步为什么成立。':`你选了 ${'ABCD'[entry.choice]}，正确答案是 ${'ABCD'[exercise.correctIndex]}。`;box.append(feedback);const solution=document.createElement('div');solution.className='generated-solution';const title=document.createElement('h5');title.textContent='详细解法';const steps=document.createElement('ol');exercise.steps.forEach(step=>{const li=document.createElement('li');li.textContent=step;steps.append(li)});const check=document.createElement('p');const checkLabel=document.createElement('strong');checkLabel.textContent='验算 / 验证：';check.append(checkLabel,document.createTextNode(exercise.check));const pitfall=document.createElement('p');const pitfallLabel=document.createElement('strong');pitfallLabel.textContent='容易错在：';pitfall.append(pitfallLabel,document.createTextNode(exercise.pitfall));solution.append(title,steps,check,pitfall);box.append(solution)}result.append(box)}

// AI Q&A: the key, conversation and optional image live only in this page's memory.
const askMessages=[];
let askImage=null;
let askLesson=null;
let askPending=false;
const askQuestion=document.getElementById('ask-question');
const askStatus=document.getElementById('ask-status');
const askThread=document.getElementById('ask-thread');
const askMode=document.getElementById('ask-mode');
const askModel=document.getElementById('ask-model');
const askKey=document.getElementById('ask-key');
askKey.addEventListener('input',()=>{apiKeyMemory=askKey.value;document.querySelectorAll('[data-practice-key]').forEach(input=>{if(input!==document.activeElement)input.value=apiKeyMemory})});
function askNotice(message,isError=false){askStatus.textContent=message;askStatus.classList.toggle('error',isError)}
function askBubble(role,content){const welcome=askThread.querySelector('.ask-welcome');if(welcome)welcome.remove();const item=document.createElement('div');item.className='ask-bubble '+role;const label=document.createElement('span');label.textContent=role==='user'?'你':'AI 老师';const body=document.createElement('div');body.textContent=content;item.append(label,body);askThread.append(item);item.scrollIntoView({behavior:'smooth',block:'end'});return item}
function askFromContext(mode,question,lesson){askMode.value=mode;askLesson=lesson||null;askQuestion.value=question;switchView('ask');askQuestion.focus()}
document.getElementById('quantity-ask').addEventListener('click',()=>{const l=lessons.find(x=>x.id===currentLesson)||lessons[0];askFromContext('quantity',`我在学习「${l.title}」，请从最基础的概念讲解，并告诉我为什么要用「${l.formula}」。`,l.id)});
document.getElementById('spatial-ask').addEventListener('click',()=>askFromContext('spatial','立方体展开图里，我还是不能理解相对面是怎么找出来的。请结合 A-F、B-D、C-E 的例子一步步讲解。','cube'));
document.querySelectorAll('[data-example]').forEach(button=>button.addEventListener('click',()=>{askQuestion.value=button.dataset.example;askQuestion.focus()}));
document.getElementById('ask-key-toggle').addEventListener('click',e=>{const showing=askKey.type==='text';askKey.type=showing?'password':'text';e.currentTarget.textContent=showing?'显示':'隐藏';e.currentTarget.setAttribute('aria-label',showing?'显示 API Key':'隐藏 API Key')});
document.getElementById('ask-image').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>4*1024*1024){askNotice('请选择不超过 4 MB 的 PNG、JPEG 或 WebP 图片。',true);e.target.value='';return}if(!MODEL_CONFIG[askModel.value].supportsImage){askModel.value=askModel.value.startsWith('deepseek')?'deepseek-flash':'glm-5.3-flash';askNotice(`已切换到支持图片的 ${MODEL_CONFIG[askModel.value].label}。`)}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});askImage={name:file.name,data};const preview=document.getElementById('ask-image-preview');preview.hidden=false;preview.textContent='已附图：'+file.name+'　';const remove=document.createElement('button');remove.type='button';remove.textContent='移除 ×';remove.addEventListener('click',()=>{askImage=null;preview.hidden=true;preview.textContent='';e.target.value='' });preview.append(remove)}catch{askNotice('图片读取失败，请重新选择。',true)}});
askModel.addEventListener('change',()=>{if(askImage&&!MODEL_CONFIG[askModel.value].supportsImage){askModel.value=askModel.value.startsWith('deepseek')?'deepseek-flash':'glm-5.3-flash';askNotice(`含图片的问题需要使用支持图片的模型，已切换到 ${MODEL_CONFIG[askModel.value].label}。`,true)}});
function directTutorSystem(){const lesson=lessons.find(x=>x.id===askLesson);const direction={auto:'自动判断题型',quantity:'数量关系',spatial:'图形推理',review:'错题复盘'}[askMode.value]||'自动判断题型';return `你是行测辅导老师，正在帮助考生理解而不是只报答案。答疑方向：${direction}。${lesson?`当前知识点：${lesson.title}。基础规则：${lesson.formula}。`:''}请先判断题型和关键条件，再用中文分步骤讲解；说明为什么这样做，给出验算或排除方法，并指出一个易错点。遇到信息不足时先说明缺少什么，不要编造题干。`}
async function directModel(model,key,messages,maxTokens=1800){const config=MODEL_CONFIG[model];if(!config)throw new Error('请选择支持的模型。');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(config.endpoint,{method:'POST',headers:{Authorization:`Bearer ${key}`,'Content-Type':'application/json'},body:JSON.stringify({model,messages,stream:false,max_tokens:maxTokens,...(config.thinking?{thinking:{type:'enabled'},reasoning_effort:'low'}:{})}),signal:controller.signal});let data={};try{data=await response.json()}catch{}if(!response.ok){if(response.status===401||response.status===403)throw new Error(`${config.provider} API Key 验证失败，或该 Key 无权使用所选模型。`);if(response.status===429)throw new Error(`${config.provider} 调用已达到限额或当前繁忙，请检查账户额度。`);throw new Error(`${config.provider} 接口返回错误（${response.status}）。`)}const content=data?.choices?.[0]?.message?.content;if(typeof content!=='string'||!content.trim())throw new Error('模型没有返回正文。');return content.trim()}catch(error){if(error?.name==='AbortError')throw new Error(`浏览器直连${config.provider}超时，请检查网络或模型额度。`);throw error}finally{clearTimeout(timer)}}
const connectionStatus=document.getElementById('ask-connection-status');
document.getElementById('ask-test-connection').addEventListener('click',async()=>{const key=askKey.value.trim();if(!key){connectionStatus.textContent='请先输入 API Key';connectionStatus.className='error';askKey.focus();return}const button=document.getElementById('ask-test-connection');button.disabled=true;connectionStatus.className='';connectionStatus.textContent='测试中…';try{await directModel(askModel.value,key,[{role:'user',content:'只回复“连接成功”，不要添加其他文字。'}],24);connectionStatus.textContent=`连接成功 · ${MODEL_CONFIG[askModel.value].label}`;askNotice('连接成功，可以发送问题了。')}catch(error){connectionStatus.textContent=error.message||'连接失败';connectionStatus.className='error';askNotice('连接失败：'+(error.message||'请检查 Key、模型权限和网络。'),true)}finally{button.disabled=false}});
document.getElementById('ask-form').addEventListener('submit',async e=>{e.preventDefault();if(askPending)return;const question=askQuestion.value.trim();const apiKey=askKey.value.trim();if(question.length<2){askNotice('请先写下具体问题。',true);askQuestion.focus();return}if(!apiKey){askNotice('请在右侧输入你的模型 API Key。',true);askKey.focus();return}askPending=true;document.getElementById('ask-submit').disabled=true;const selectedLabel=MODEL_CONFIG[askModel.value].label;askNotice(`正在连接 ${selectedLabel} 并整理步骤…`);const loading=askBubble('assistant','正在思考并整理步骤…');const requestBody={apiKey,model:askModel.value,mode:askMode.value,lesson:askLesson||undefined,question,image:askImage?.data,history:askMessages.slice(-8)};let answer='';let skill='';try{try{const userContent=askImage?[{type:'text',text:question},{type:'image_url',image_url:{url:askImage.data}}]:question;answer=await directModel(askModel.value,apiKey,[{role:'system',content:directTutorSystem()},...askMessages.slice(-8),{role:'user',content:userContent}]);skill=askMode.value;askNotice(`已直连 ${selectedLabel}，回答已生成。`)}catch(directError){askNotice('浏览器直连未完成，正在切换服务端转发…');const response=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(requestBody),cache:'no-store',credentials:'same-origin'});const data=await response.json();if(!response.ok)throw new Error(data.error||directError.message||'请求失败，请稍后重试。');answer=data.answer;skill=data.skill||askMode.value}loading.remove();askBubble('user',question+(askImage?'（附题目图片）':''));askBubble('assistant',answer);askMessages.push({role:'user',content:question.slice(0,2950)+(askImage?'（附图片；图片仅本轮可见）':'')},{role:'assistant',content:answer.slice(0,3000)});askQuestion.value='';askImage=null;const preview=document.getElementById('ask-image-preview');preview.hidden=true;preview.textContent='';document.getElementById('ask-image').value='';askLesson=null;document.getElementById('skill-route').textContent={quantity:'已调用 · 数量关系解题规则',spatial:'已调用 · 图形推理识别规则',review:'已调用 · 错题结构化复盘规则'}[skill]||'已匹配答疑规则';askNotice('回答已生成。可以继续追问。')}catch(error){loading.remove();askNotice(error.message||'模型连接失败，请检查 API Key、模型权限和网络。',true)}finally{askPending=false;document.getElementById('ask-submit').disabled=false}});
